const InNeed = () => {
  const { lang } = useContext(LanguageContext);
  const { height } = useContext(ScreenModeAndSizeContext);
  const { mobile } = useContext(ScreenModeAndSizeContext);

  const mobileDesktopClass = () => {
    if (mobile) return "mobile";
    return "desktop";
  };

  return (
    <section
      style={{ maxHeight: height }}
      className={`${styles.section} section`}
    >
      <div className={`${styles.block}`}>
        <div className={`${styles.title} h1 ${mobileDesktopClass()}`}>
          <h1 className={`bigNumb ${styles.lineHeight}`}>
            {InNeedText.titleNumber[lang]}
          </h1>
          <h2 className={`${styles.colorModBlack}`}>
            <span className={`uppercase ${styles.fontSizeBig}`}>
              {InNeedText.ukrainians[lang]}
            </span>
            {InNeedText.areIn[lang]}
          </h2>
          <h2 className={`${styles.colorModBlack} `}>
            <span className={`${styles.fontPlayfair} `}>
              {InNeedText.need[lang]}
            </span>
            {InNeedText.for[lang]}
          </h2>
          <h2 className={`${styles.colorModBlack} `}>
            <span className={`${styles.fontPlayfair} `}>
              {InNeedText.prosthetics[lang]}
            </span>
            {InNeedText.asThe[lang]}
          </h2>
          <h2 className={`uppercase ${styles.colorModBlack}`}>
            {InNeedText.result[lang]}
          </h2>
          <h2 className={`${styles.colorModBlack}`}>
            {InNeedText.ofThe[lang]}
            <span className={`uppercase`}>{InNeedText.war[lang]}</span>
          </h2>
          {/* {TitleSvg()} */}
          {""}
        </div>
        <div className={`${styles.text} h2 ${mobileDesktopClass()}`}>
          <h2>{InNeedText.paragraph[lang]}</h2>
        </div>
      </div>
    </section>
  );
};

export default InNeed;
